/**
 * Session memory is a journal of what every session of this agent did, so
 * later sessions can recall and build on past work.
 *
 * The write side is {@link memoryHook}, authored as a thin re-export at
 * `bot/hooks/memory.ts`. After each turn it appends one record to
 * `<stateRoot>/memory/journal.jsonl`.
 *
 * There is no read-side API. The framework symlinks `<stateRoot>/memory`
 * into every session workspace as `memory/`, so agents read the journal
 * with their normal file tools (`instructions.md` points them at it). That
 * filesystem visibility is why memory does not route through
 * `defineStorage` sinks, which are opaque to the model. A custom
 * {@link MemoryBackend} supplies its own read path.
 *
 * On Cursor-managed hosting the default is {@link agentStoreMemoryBackend}:
 * the journal survives deployment replacement and is mirrored locally so
 * file tools keep the same read path. Local development uses
 * {@link fileMemoryBackend}.
 */
import { randomUUID } from "node:crypto";
import { appendFile, mkdir, rename, stat, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { agentStoreKeys } from "./files.js";
import { isCursorHostedFilesAvailable, } from "./files-backends/cursor-hosted.js";
import { defineHook } from "./hooks.js";
import { createStoreApiClient, isStoreApiLaneEnabled, } from "./internal/cursor/store-api-client.js";
import { MEMORY_DIR_NAME } from "./internal/memory-dir.js";
/**
 * Local default backend: append-only JSONL at `<stateRoot>/memory/journal.jsonl`
 * in the directory the framework symlinks into session workspaces. Rotated
 * segments stay alongside as `journal-<epoch-ms>.jsonl`.
 */
export function fileMemoryBackend(options = {}) {
    const maxJournalBytes = options.maxJournalBytes ?? 5 * 1024 * 1024;
    // Event dispatch is serialized per session but concurrent across
    // sessions, so appends to the shared journal are chained per path. A
    // failed append must not poison the chain for later turns.
    const appendChains = new Map();
    // Same-millisecond rotations must not reuse a segment name; POSIX
    // rename would silently replace the earlier archive.
    let rotationSeq = 0;
    return {
        async appendTurn(record, ctx) {
            const dir = join(ctx.stateRoot, MEMORY_DIR_NAME);
            const path = join(dir, "journal.jsonl");
            const prior = appendChains.get(path) ?? Promise.resolve();
            const next = prior
                .catch(() => { })
                .then(async () => {
                await mkdir(dir, { recursive: true });
                const size = (await stat(path).catch(() => undefined))?.size ?? 0;
                if (size >= maxJournalBytes) {
                    rotationSeq += 1;
                    await rename(path, join(dir, `journal-${Date.now()}-${rotationSeq}.jsonl`));
                }
                await appendFile(path, `${JSON.stringify(record)}\n`, "utf8");
            });
            appendChains.set(path, next);
            await next;
        },
    };
}
/**
 * Cursor-managed journal that survives deployment replacement. Managed
 * storage owns append, read, and rotation. If managed storage is unavailable,
 * records are dropped with an error instead of falling back to a second
 * persistence path.
 */
export function agentStoreMemoryBackend(options = {}) {
    const hosted = options.hosted ?? {};
    const maxJournalBytes = options.maxJournalBytes ?? 5 * 1024 * 1024;
    // Mirror work is chained per journal key (same shape as
    // fileMemoryBackend): hydration and appends on one agent's mirror never
    // interleave, and a failed step must not poison the chain for later turns.
    const appendChains = new Map();
    // The client owns retries and typed errors; this module owns memory policy.
    const storeApiClient = options.storeApiClient ?? createStoreApiClient(hosted);
    /**
     * Keep the local journal mirror available to file tools. Hydrate it when
     * absent, then append each record only after managed storage accepts it.
     * Memory is advisory, so another process's newest records may appear on
     * the next hydration.
     */
    const hydratedMirrors = new Set();
    let mirrorRotationSeq = 0;
    const maintainLocalMirror = async (record, ctx) => {
        const dir = join(ctx.stateRoot, MEMORY_DIR_NAME);
        const path = join(dir, "journal.jsonl");
        if (!hydratedMirrors.has(path)) {
            // Appends are chained per journal key, so this guard never races
            // itself for one agent. Backstop for a session that appended before
            // any prepareSession hydration ran (e.g. a custom hook ordering).
            hydratedMirrors.add(path);
            const existing = await stat(path).catch(() => undefined);
            if (existing === undefined) {
                const content = await storeApiClient.memoryReadContent({
                    agent: ctx.agentName,
                });
                if (content !== undefined) {
                    await mirrorJournalLocally(ctx.stateRoot, content);
                }
            }
        }
        await mkdir(dir, { recursive: true });
        const size = (await stat(path).catch(() => undefined))?.size ?? 0;
        if (size >= maxJournalBytes) {
            mirrorRotationSeq += 1;
            await rename(path, join(dir, `journal-${Date.now()}-${mirrorRotationSeq}.jsonl`));
        }
        await appendFile(path, `${JSON.stringify(record)}\n`, "utf8");
    };
    /**
     * Append one record to managed storage, then update the local mirror.
     *
     * Failure policy: log and give up for this record. Memory is advisory and
     * the hook runner treats an append failure as non-fatal to the turn;
     * a failed durable write also skips the mirror.
     */
    const appendViaStoreApi = async (record, ctx) => {
        try {
            await storeApiClient.memoryAppend({ agent: ctx.agentName, record });
        }
        catch (error) {
            console.warn(`[bdk] memory.append dropped one record for "${ctx.agentName}": ${error instanceof Error ? error.message : String(error)}`);
            return;
        }
        try {
            await maintainLocalMirror(record, ctx);
        }
        catch (error) {
            console.warn(`[bdk] memory mirror update failed for "${ctx.agentName}" (journal record is durable): ${error instanceof Error ? error.message : String(error)}`);
        }
    };
    /**
     * Refresh the local mirror at session start. Soft-fail so an unavailable
     * store does not erase the existing mirror.
     */
    const hydrateMirror = async (ctx) => {
        const path = join(ctx.stateRoot, MEMORY_DIR_NAME, "journal.jsonl");
        try {
            const content = await storeApiClient.memoryReadContent({
                agent: ctx.agentName,
            });
            if (content !== undefined) {
                // Never replace the local mirror with a shorter journal. Keeping the
                // richer view avoids hiding records the agent has already seen.
                const mirroredBytes = (await stat(path).catch(() => undefined))?.size ?? 0;
                if (content.byteLength >= mirroredBytes) {
                    await mirrorJournalLocally(ctx.stateRoot, content);
                }
            }
            // Either way the read answered: skip the append path's absent-file
            // hydration for the rest of this process.
            hydratedMirrors.add(path);
        }
        catch (error) {
            console.warn(`[bdk] memory hydration failed for "${ctx.agentName}" (keeping the existing mirror): ${error instanceof Error ? error.message : String(error)}`);
        }
    };
    /** Report a missing managed-storage binding without falling back locally. */
    const refuseMisconfiguredLane = (agentName, verb) => {
        console.error(`[bdk] memory ${verb} for "${agentName}" dropped: the store API lane is unavailable (missing/foreign AGENT_SERVE_STORE_PROTOCOL pin or no provisioned store). This BDK version has no client-side journal fallback; fix the hosting pin.`);
    };
    return {
        async prepareSession(ctx) {
            // Chained on the same per-journal key as appends, so hydration never
            // interleaves with an append's mirror write.
            const key = agentStoreKeys.memoryJournal(ctx.agentName);
            const prior = appendChains.get(key) ?? Promise.resolve();
            const next = prior
                .catch(() => { })
                .then(async () => {
                if (!isStoreApiLaneEnabled(hosted)) {
                    refuseMisconfiguredLane(ctx.agentName, "hydration");
                    return;
                }
                await hydrateMirror(ctx);
            });
            appendChains.set(key, next);
            await next;
        },
        async appendTurn(record, ctx) {
            // Soft-fail by construction (appendViaStoreApi never throws), but
            // still chained per journal key: the local mirror's hydrate-then-
            // append must not interleave with itself. Availability is resolved
            // lazily for each append.
            const key = agentStoreKeys.memoryJournal(ctx.agentName);
            const prior = appendChains.get(key) ?? Promise.resolve();
            const next = prior
                .catch(() => { })
                .then(async () => {
                if (!isStoreApiLaneEnabled(hosted)) {
                    refuseMisconfiguredLane(ctx.agentName, "append");
                    return;
                }
                await appendViaStoreApi(record, ctx);
            });
            appendChains.set(key, next);
            await next;
        },
    };
}
/** Atomic full rewrite of the local mirror. */
async function mirrorJournalLocally(stateRoot, contents) {
    const dir = join(stateRoot, MEMORY_DIR_NAME);
    await mkdir(dir, { recursive: true });
    const tmp = join(dir, `.tmp-${randomUUID()}`);
    await writeFile(tmp, contents);
    await rename(tmp, join(dir, "journal.jsonl"));
}
/** Cursor-managed deployments use durable memory; local development uses files. */
function defaultMemoryBackend() {
    return isCursorHostedFilesAvailable() ? agentStoreMemoryBackend() : fileMemoryBackend();
}
function truncate(text, max) {
    return text.length <= max ? text : `${text.slice(0, max)}…`;
}
/**
 * Observe-only hook that journals every turn. Author it as
 * `bot/hooks/memory.ts`:
 *
 * ```ts
 * import { memoryHook } from "@grok/agent-sdk/memory";
 * export default memoryHook();
 * ```
 *
 * The journal is shared across every session — and every user — of the
 * agent. Pass your own {@link MemoryHookOptions.backend} to change where
 * memories live; delete the hook file to opt out entirely.
 */
export function memoryHook(options = {}) {
    const backend = options.backend ?? defaultMemoryBackend();
    const maxTextLength = options.maxTextLength ?? 2000;
    // Inbound message per turn (truncated at receipt so large pastes are not
    // retained), keyed `<sessionId>/<turnId>` — `message.received` and the
    // turn-end events share a turnId. Entries drop at turn end and any
    // stragglers (turns that never reached a terminal event) at session end.
    const pendingMessages = new Map();
    const pendingKey = (ctx, turnId) => `${ctx.session.id}/${turnId ?? "?"}`;
    const record = async (ctx, turnId, status, result, usage) => {
        const key = pendingKey(ctx, turnId);
        const userMessage = pendingMessages.get(key);
        pendingMessages.delete(key);
        const entry = {
            at: new Date().toISOString(),
            sessionId: ctx.session.id,
            channelId: ctx.channel.id,
            status,
        };
        if (ctx.session.title !== undefined) {
            entry.title = ctx.session.title;
        }
        if (ctx.session.sdkAgentId !== undefined) {
            entry.sdkAgentId = ctx.session.sdkAgentId;
        }
        if (userMessage !== undefined) {
            entry.userMessage = userMessage;
        }
        if (result !== undefined) {
            entry.result = truncate(result, maxTextLength);
        }
        if (usage !== undefined) {
            entry.usage = usage;
        }
        await backend.appendTurn(entry, {
            stateRoot: ctx.stateRoot,
            agentName: ctx.agent.name,
        });
    };
    const sweepSession = (ctx) => {
        for (const key of pendingMessages.keys()) {
            if (key.startsWith(`${ctx.session.id}/`)) {
                pendingMessages.delete(key);
            }
        }
    };
    return defineHook({
        events: {
            async "session.started"(_event, ctx) {
                // Bring the mirror (the workspace symlink read path) up to date
                // before the session's first turn reads it. Backends without a
                // prepareSession (plain files) have nothing to freshen. Soft-fail:
                // hydration is a freshness upgrade, never a turn blocker.
                try {
                    await backend.prepareSession?.({
                        stateRoot: ctx.stateRoot,
                        agentName: ctx.agent.name,
                    });
                }
                catch (error) {
                    console.warn(`[bdk] memory hydration at session start failed: ${error instanceof Error ? error.message : String(error)}`);
                }
            },
            async "message.received"(event, ctx) {
                pendingMessages.set(pendingKey(ctx, event.turnId), truncate(event.data.text, maxTextLength));
            },
            async "turn.completed"(event, ctx) {
                await record(ctx, event.turnId, "completed", event.data.result, event.data.usage);
            },
            async "turn.failed"(event, ctx) {
                await record(ctx, event.turnId, "failed", event.data.message, undefined);
            },
            async "session.completed"(_event, ctx) {
                sweepSession(ctx);
            },
            async "session.failed"(_event, ctx) {
                sweepSession(ctx);
            },
        },
    });
}
